import{_ as t,o as a,c as _,a4 as r}from"./chunks/framework.C3unmAF4.js";const f=JSON.parse('{"title":"稻田有望迈入“智能抑草”时代​——智慧农业催生消费新场景","description":"","frontmatter":{"sidebar":false,"aside":false,"editLink":false,"lastUpdated":false,"prev":false,"next":false,"title":"稻田有望迈入“智能抑草”时代​——智慧农业催生消费新场景","date":"2026-08-15T00:00:00.000Z","source":"农业农村部智慧农业专题","category":"news","link":"https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202608/t20260804_6486431.htm","summary":"稻田间不见弯腰除草的农户,一台黑色方形抑草机器人正自主穿梭作业;机器人顶部搭载的太阳能板持续蓄能,按规划路线精准避开秧苗;机器人底部除草刷将尚未扎根的杂草搅起,高效完成稻田抑草作业……这是科技日报记者近日在上海西郊稻田里看到的一幕。未来,它有望成为智慧农业新消费的典型场景。\\n机器人在田间开展抑草作业。受访单位供图\\n...\\n","contentHash":"a03dd4e7e1d4e3b03d246839c6450f23","tags":["智慧农业","行业资讯"]},"headers":[],"relativePath":"news/2026-08-15-稻田有望迈入-智能抑草-时代-智慧农业催生消费新场景.md","filePath":"news/2026-08-15-稻田有望迈入-智能抑草-时代-智慧农业催生消费新场景.md"}'),n={name:"news/2026-08-15-稻田有望迈入-智能抑草-时代-智慧农业催生消费新场景.md"};function p(s,e,o,l,d,c){return a(),_("div",null,[...e[0]||(e[0]=[r('<h1 id="稻田有望迈入-智能抑草-时代​——智慧农业催生消费新场景" tabindex="-1">稻田有望迈入“智能抑草”时代​——智慧农业催生消费新场景 <a class="header-anchor" href="#稻田有望迈入-智能抑草-时代​——智慧农业催生消费新场景" aria-label="Permalink to &quot;稻田有望迈入“智能抑草”时代​——智慧农业催生消费新场景&quot;">​</a></h1><blockquote><p>来源: <a href="https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202608/t20260804_6486431.htm" target="_blank" rel="noreferrer">农业农村部智慧农业专题</a><br> 日期: 2026-08-15 摘要: 稻田间不见弯腰除草的农户,一台黑色方形抑草机器人正自主穿梭作业;机器人顶部搭载的太阳能板持续蓄能,按规划路线精准避开秧苗;机器人底部除草刷将尚未扎根的杂草搅起,高效完成稻田抑草作业……这是科技日报记者近日在上海西郊稻田里看到的一幕。未来,它有望成为智慧农业新消费的典型场景。 机器人在田间开展抑草作业。受访单位供图 ...</p></blockquote><p>机器人在田间开展抑草作业。受访单位供图</p><p>过去,智慧农机装备多集中于大型收割、播种设备等,如今伴随着数字化、无人化技术向农业领域拓展应用,精准除草、无人耕种、自动植保等设备成为种植主体采购热点,开辟了全新消费赛道。中商产业研究院发布的研究报告显示,2020年至2024年中国农机市场复合年均增长率为7.8%,2025年中国农机市场规模为907亿元,2030年市场规模将达到1467亿元,其中智能农机市场规模达1039亿元。这意味着,智能农机将在农业生产中发挥越来越重要的作用。</p><p>记者在上海市嘉定区外冈镇智慧农场周泾基地看到,插秧后的稻田里,一台机器人正缓缓前进。机器底部的除草刷将田里的积水搅浑——这并不是在单纯“和稀泥”。“就像家里的扫地机器人,一启动,它自己就会满屋子跑,对地板进行清洁。”上海外冈农机服务专业合作社负责人孙佳赟打了个比方,“只不过这台‘扫地机器人’,扫的是稻田里的杂草。”</p><p>机器人在田间开展抑草作业。受访单位供图</p><p>这台抑草机器人是智能农机创新的一个典型案例。以往,水稻苗期杂草争夺养分、诱发病虫害,传统模式面临“两难”:人工除草耗时费力、用工成本居高不下;化学除草剂易造成水土污染,长期使用还会催生杂草抗药性。而这款稻田版“扫地机器人”给出了绿色解决方案:依靠两侧毛刷将尚未扎根的杂草搅起,隔绝光照抑制杂草光合作用,纯物理除草、零化学残留;它搭载太阳能供电系统,在晴天条件下可连续作业8小时,续航能力出色。</p><p>不过,这款机器人原本并非如此高能。在设备落地初期,它仅能无规则漫游,作业精度不足。上海司南卫星导航技术股份有限公司工程师吴义生介绍,“我们给机器人加装了司南北斗导航驾驶系统后,它能够直线行走,在稻田里有规则地抑草。”</p><p>如今,工作人员通过系统设置,可在屏幕上精确划定作业区域,并实时查看机器人的行进路径、速度、方向和位置等信息。“好比扫地机器人,你能设定它只清扫厨房或者餐厅这些最需要打扫的地方。”孙佳赟说,“这既提升了抑草效率,也避免了对秧苗的重复碾压,作业更加精准可靠。”</p><p>工作人员可在屏幕上实时查看机器人作业信息。受访单位供图</p><p>据介绍,当前,这款抑草机器人仍处于田间试验阶段,若后续试用效果理想,上海将在周边稻田批量推广。专家表示,国内农机企业纷纷布局北斗导航、边缘感知、自主行走等技术,打造适配水稻、果蔬等不同作物的细分智能装备,拓展农机产业消费空间。</p><p>“尽管稻田机器人抑草还有进一步提升能效的空间,但智慧农业时代正加速到来。”上海市农业科学院科技兴农办主任、上海市农村专业技术协会副理事长谢祝捷研究员认为,科技赋能农业生产,将持续激活智慧农业新质生产力。</p><p><a href="https://www.moa.gov.cn/ztzl/zhnyzxd/xydt/202608/t20260804_6486431.htm" target="_blank" rel="noreferrer">阅读原文</a></p>',13)])])}const h=t(n,[["render",p]]);export{f as __pageData,h as default};
